  'adv.back': "戻る",
  'adv.backToList': "高度な機能の一覧に戻る",
  'advanced.stepByStepFlex': "ステップごと — 柔性法",
  'advHelp.fm.label': "ステップごと — 柔性法（力法）",
  'advHelp.fm.text': "力法で構造を 1 ステップずつ解きます：不静定次数、余剰力と基本構造の選択、状態 0 と各単位状態のモーメント図、モールの積分による柔性係数 δij と荷重項 δi0、適合方程式、重ね合わせ、そして剛性法との最終照合。2D と 3D の骨組とトラスに対応します。",
  'fm.wizardTitle': "ステップごと — 柔性法",
  'fm.step1Name': "不静定次数",
  'fm.step2Name': "基本構造と余剰力",
  'fm.step3Name': "状態 0：基本構造に作用する荷重",
  'fm.step4Name': "単位状態 Xi = 1",
  'fm.step5Name': "柔性係数 δij",
  'fm.step6Name': "荷重項 δi0",
  'fm.step7Name': "適合方程式",
  'fm.step8Name': "重ね合わせ",
  'fm.step9Name': "剛性法との照合",
  'fm.banner': "2D · 骨組とトラス · オイラー・ベルヌーイのバー（せん断変形は無視）",
  'fm.s1.explanation': "静力学の釣合い式だけではすべての力を求められない構造を<strong>不静定</strong>といいます。<strong>不静定次数</strong> GH は、余分な力がいくつあるかを数えたものです：GH = 未知数 − 方程式。",
  'fm.s1.reactions': "支点反力（r）",
  'fm.s1.springs': "ばねの力",
  'fm.s1.bars': "バーの未知の力",
  'fm.s1.barsNote': "骨組の部材は 3 つ（片端の N、V、M。もう一端は部材自身の釣合いから決まります）で、ヒンジ端 1 つにつき 1 つ少なくなります。トラスのバーは 1 つ（N）です。",
  'fm.s1.equations': "釣合い方程式",
  'fm.s1.equationsNote': "節点ごとに 2 つ（ΣFx = 0、ΣFz = 0）。さらに、モーメントが存在しうる場所では ΣM = 0 を加えます：剛接合された部材端、または回転を拘束する支点です。",
  'fm.s1.hyper': "力が {gh} 個多くあります。この方法では、足りない {gh} 個の方程式を変形の適合条件から求めます。",
  'fm.s1.iso': "GH = 0：構造は静定です。静力学だけで十分で、この方法の未知数はありません。それでも手順を追うと、各ステップで何を意味するかがわかります。",
  'fm.iso.s2': "GH = 0 では解放するものがありません。基本構造は構造そのものです。",
  'fm.iso.s3': "状態 0 がそのまま答えです。構造は静定なので、実際の荷重を載せるだけで最終的な図が直接得られます。",
  'fm.iso.none': "このステップですることはありません。余剰力がないので、単位状態も柔性係数も適合方程式もありません。釣合いだけで状態 0 の答えが得られました。",
  'fm.iso.s8': "M = M₀：余剰力がないので、重ね合わせるものはありません。",
  'fm.s2.explanation': "GH 個の力を選び、これを<strong>余剰力</strong> X₁…Xₙ として取り除きます。残ったものが<strong>基本構造</strong>で、静定かつ安定です。Xᵢ は、その上に作用する未知の荷重として扱います。",
  'fm.s2.original': "実際の構造",
  'fm.s2.primary': "基本構造（余剰力を荷重として表示）",
  'fm.s2.list': "選んだ余剰力",
  'fm.s2.why': "選び方：まず固定端モーメント、次に中間支点の反力、次にトラスのバー、そして閉じたループを開く必要があれば 1 つの部材の切断。得られた基本構造が安定であることは確認済みです。",
  'fm.s2.prescribed': "この支点には強制変位 Δ = {d} m があります。これは適合方程式の右辺に入ります。",
