  'fm.banner3d': "3D · 立体骨組とトラス · オイラー・ベルヌーイのバー、サン・ブナンのねじり",
  'fm.s1.barsNote3d': "立体骨組の部材は 6 つ（N、Vy、Vz、T、My、Mz）で、端部で解放された曲げモーメント 1 つにつき 1 つ減り、ねじりの解放ではねじりモーメントが 1 つ減ります。トラスのバーは 1 つ（N）です。",
  'fm.s1.equationsNote3d': "節点ごとに 6 つ（3 つの力と 3 つのモーメント）から、どの部材も抵抗しない回転を除きます。その方向にはつり合わせるモーメントがないためです。",
  'fm.s5.explanation3d': "δᵢⱼ は、Xⱼ = 1 によって生じる Xᵢ 方向の変位です。空間では、各バーが軸力、2 つの平面の曲げ、ねじりで働きます：",
  'fm.src.torsion': "ねじり ∫t·t/GJ",
  'fm.diagram.pick': "図：",
  'fm.s3.explanation': "静定な基本構造を実際の荷重のもとで解き、図 M₀ と力 N₀ を得ます。実際の構造では Xᵢ で拘束されている位置で、基本構造は自由にたわみます。",
  'fm.s4.explanation': "基本構造を荷重なしで、1 つの余剰力だけを 1 として解きます：Xᵢ = 1。各状態から図 mᵢ が得られます。線形性により、実際の状態は M₀ + Σ Xᵢ·mᵢ になります。",
  'fm.s3.reactions': "反力",
  'fm.s3.endMoments': "バー端のモーメント",
  'fm.s3.bar': "バー",
  'fm.s3.node': "節点",
  'fm.s3.drawn': "モーメント図は引張側に描いています。",
  'fm.s5.explanation': "δᵢⱼ は、Xⱼ = 1 によって生じる Xᵢ 方向の変位です。仮想仕事の原理（モール）により：",
  'fm.s5.symmetry': "行列は対称です：δᵢⱼ = δⱼᵢ（マクスウェル・ベッティ）。",
  'fm.s5.pick': "係数を選ぶと、その出どころが表示されます：",
  'fm.s5.breakdown': "各バーの寄与",
  'fm.s5.check': "検算：剛性法で解いた基本構造の変位として読むと、同じ係数は {v} です。",
  'fm.mx.explanation': "方法の全体を 1 画面に示します：柔性マトリクス [δ]、荷重項、解。係数をタップすると、その積になっている 2 つの単位図が表示されます。",
  'fm.mx.clickCell': "係数をタップ",
  'fm.mx.hinges': "ヒンジ：ヒンジではモーメントがゼロなので、すべての mᵢ がそこで 0 になり、その隣のバーが [δ] に与える寄与は小さくなります。ヒンジ 1 つにつき GH も 1 減ります。余剰力が 1 つ減り、[δ] の行と列も 1 つずつ減ります。",
  'fm.mx.truss': "トラスのバーは軸力だけを負担します。各係数への寄与は nᵢ·nⱼ·L/EA で、バーに沿って一定であり、曲げの項はありません。",
  'fm.mx.barRedundant': "取り除いたバーは余剰力です。Xᵢ = 1 のときのそのバー自身の伸び L/EA が δᵢᵢ に入ります。残される隙間は、バー自身の変形で閉じなければなりません。",
  'fm.mx.agrees': "同じ構造を剛性法で解くと、同じ反力と端部の力が得られます。",
  'fm.s6.explanation': "δᵢ₀ は、状態 0（実際の荷重を受ける基本構造）における Xᵢ 方向の変位です：",
  'fm.s6.extras': "温度変化では ∫ nᵢ·α·ΔT dx + ∫ mᵢ·α·Δt/h dx が加わります。基本構造に残る沈下する支点では −Σ Rₖ⁽ⁱ⁾·Δₖ が加わります。",
  'fm.src.bending': "曲げ ∫m·m/EI",
  'fm.src.axial': "軸力 ∫n·n/EA",
