  'fm.src.bar': "取り除いたバー自身、L/EA",
  'fm.src.settlement': "沈下",
  'fm.total': "合計",
  'fm.s7.explanation': "実際の構造では、各 Xᵢ 方向の変位は、その拘束が課す値で、ほとんどの場合ゼロです。状態を重ね合わせると：Σⱼ δᵢⱼ·Xⱼ + δᵢ₀ = Δᵢ。GH 個の方程式、GH 個の未知数です。",
  'fm.s7.system': "連立方程式",
  'fm.s7.solution': "解",
  'fm.s7.units': "力の単位は kN、モーメントは kN·m。",
  'fm.s8.explanation': "Xᵢ がわかれば、あとはすべて重ね合わせで求まります：M = M₀ + Σ Xᵢ·mᵢ。N、V、反力も同様です。",
  'fm.s9.explanation': "同じ構造を剛性法で解いても、同じ答えになるはずです。2 つの方法、1 つの構造：",
  'fm.s9.ok': "一致しました：最大の差は {d} で、最大の力の {pct} です。",
  'fm.s9.bad': "一致しません — 最大の差は {d} です。",
  'fm.s9.flex': "柔性法",
  'fm.s9.stiff': "剛性法",
  'fm.err.axialTrussPoint3d': "3D の柔性法のステップ表示では、トラス部材内部の軸方向の集中荷重を復元できません。剛性法を使用してください。",
  'fm.err.hypostatic': "構造はメカニズムです（GH < 0）。解けません。",
  'fm.err.noRedundants': "安定した基本構造が得られる余剰力の選び方がありません。構造は一部がメカニズムである可能性があります。",
  'fm.err.unstable': "構造が安定ではありません。",
  'fm.err.only2d': "柔性法のステップ表示は 2D で利用できます。",
  'fm.err.unsupported': "このモデルには、ステップ表示が扱えないもの（拘束またはコネクタ）があります。",
  'fm.err.tooHyperstatic': "GH = {gh}：手計算で追うには余剰力が多すぎます（上限 {max}）。剛性法のステップ表示ならこの構造を表示できます。",
  'advanced.whatIf': "探索（もし…なら？）",
