  'ex.3d-building': "5 階建て RC ラーメン、スラブなし",
  'ex.3d-building.desc': "部材のみで構成された 5 階建てのコンクリート建物で、固定荷重、積載荷重、風荷重、地震荷重を載せています。",
  'ex.pro-edificio-7p': "7 階建て RC 建物",
  'ex.pro-edificio-7p.desc': "エレベーターと階段のある集合住宅：スラブと壁はシェル、各階に剛なダイアフラム、風荷重と用途別の荷重。",
  'ex.rc-qa-diagnostic': "風荷重と地震荷重を受ける小さな RC ラーメン",
  'ex.rc-qa-diagnostic.desc': "両方向の風荷重と地震荷重を受ける 2 層のコンクリートラーメン。各ケースは独自の符号をもちます。",
  'ex.rc-qa-diagnostic-shells': "RC QA 診断シェル（PRO）",
  'ex.rc-qa-diagnostic-shells.desc': "梁・柱の上の RC スラブ（曲げ）と壁（膜）、および曲線梁。すべてのシェルのコンター成分がどこかで変化します",
