  'ex.cad-arch-structure-dxf.desc': "構造の注記付き平面図を含む DXF から生成した、10 階建てのコンクリート草案。仮定が記録されています。",
  'ex.cad-arch-only-dxf': "DXF から：建築のみ",
  'ex.cad-arch-only-dxf.desc': "建築のみの DXF から提案した 10 階建ての草案で、すべての部材が仮定です。",
