  'pro.examples.groupValidation': "検証モデル",
  'ex.validation-01': "検証 01 · スラブ付きの鉄骨造建物",
  'ex.validation-01.desc': "鉄骨のラーメンと、シェルでメッシュ分割したコンクリートのスラブおよびコア壁をもつ 3 階建ての建物を、公表された構造に 1 対 1 で、番号付けとメッシュも含めてモデル化しています。梁は端部オフセットによりスラブ中央面の下にあり、スラブの圧力は面荷重です。",
  'ex.validation-01.purpose': "検証 / スラブ / オフセット",
  'pro.tagValidation': "検証",
  'ex.validation-06': "検証 06 · 水平力を受ける平面ラーメン",
  'ex.validation-06.desc': "2 スパン 5 階建ての鉄骨ラーメンを、公表された構造に 1 対 1 で、番号付けも含めてモデル化しています。元のプログラムが生成した地震力は節点荷重として加え、質量を作るためだけの 2 つの鉛直荷重ケースは通常のケースとして残しています。断面は断面性能で与え、せん断変形を含みます。",
  'ex.validation-06.purpose': "検証 / 地震 / せん断",
  'ex.validation-02': "検証 02 · トラスの軽量倉庫",
  'ex.validation-02.desc': "切妻トラスの門形ラーメン 3 組、母屋、ブレーストラスをもつ鉄骨倉庫を、公表された構造に 1 対 1 で、番号付けも含めてモデル化しています。剛接合、全体座標の端部オフセット、母屋のロール角は元のとおりで、弦材の荷重は全体軸と局所軸で与えています。",
  'ex.validation-02.purpose': "検証 / トラス / オフセット",
  'ex.validation-03': "検証 03 · 壁のある倉庫",
  'ex.validation-03.desc': "四辺形シェルでメッシュ分割した 2 枚のコンクリート壁が、4 本のトラスと 5 本の縦方向の溝形鋼からなる鋼製屋根を支える倉庫を、公表された構造に 1 対 1 で、番号付けとメッシュも含めてモデル化しています。山形鋼は主軸まわりで与え、各部材のロールは元のとおりです。",
  'ex.validation-03.purpose': "検証 / 壁 / シェル",
  'ex.validation-04': "検証 04 · クレーン走行路のある工場ハンガー",
  'ex.validation-04.desc': "屋根トラス、扉、付属棟、クレーン走行路、パイプラックをもつ鉄骨ハンガーを、公表された構造に 1 対 1 で、番号付けも含めてモデル化しています：部材 2482 本（多くは端部がピン）と荷重ケース 22 個。ケースは線形で解き、各組合せは終局荷重で P-Delta により解きます。元のプログラムはケースも P-Delta で解いています。元の部材検定は再現していません。安定した二次解析のつり合いが存在しない組合せは、力を公表せずに一覧に載せています。",
  'ex.validation-04.purpose': "検証 / P-Delta / 解放",
  'ex.validation-05': "検証 05 · 支線タワー",
  'ex.validation-05.desc': "高さ 57.6 m の三角形の格子タワーを、3 つのアンカーへの 18 本の支線で支える構造を、公表された構造に 1 対 1 で、番号付けも含めてモデル化しています。支線は引張のみで働き、組合せはケースの和で、元のとおり各々が独自の有効集合をもちます。風荷重は支線にもかかります。",
  'ex.validation-05.purpose': "検証 / 引張のみ / 重ね合わせ",
  'ex.validation-07': "検証 07 · 床荷重のある建物",
  'ex.validation-07.desc': "不整形な平面をもつ 4 階建てのコンクリート建物を、公表された構造に 1 対 1 で、番号付けも含めてモデル化しています。床荷重はすでに台形として梁に分配され、各部材で切り分けられています。各階は剛なダイアフラムで、自重は固定荷重のケースに含まれています。",
  'ex.validation-07.purpose': "検証 / 床 / ダイアフラム",
