  'project.importHelp': "モデルをスプレッドシートのモデルに置き換えます。先にテンプレートをダウンロードしてください。シート、列、それぞれの例が入っており、このインポーターが読み込める唯一の Excel 形式です。.ded を開くには、上の「開く」を使います。DXF と IFC は PRO にあります。",
  'project.exportViewHelp': "レポートや試験用の図：構造、その図、釣り合いのとれた自由体を、白地にすっきり描画します。形式はダイアログで選びます：SVG（ベクター、編集や印刷用）、PNG、JPG。コピーして文書にそのまま貼り付けることもできます。",
  'project.exportReportHelp': "提出する文書です。含める内容を選べます：モデルデータ、荷重、運動学的解析、釣り合いのとれた自由体、各結果（表、図、またはその両方）。形式は PDF、Word、HTML です。",
