  'flex.out.checkInputs': "入力を確認してください",
  'flex.scope': "8 枚のシートすべてをセル単位で比較しており、複鉄筋のブロック、6 つの特性点、およびそれらが描く相互作用の系列も含みます。差異として明記する点は次のとおりです：円形断面はワークブックより約 0.6 % 軽くなります。二軸の曲面切断は、ワークブックが圧縮域を離散化する象限の中ほどで最大 0.6 % 大きくなります。円形のシートでは、ワークブックの軸力上限でのモーメントは、自身の格子の隙間をまたぐ直線の弦であり、曲線を 4.4 % 過大評価していますが、ここでは曲線上の点です。そして、鋼材が 1 段に収まらなくなると、ここでは鉄筋を積み重ね、d をその群の図心までとするため、常に 1 段と仮定するワークブックより多くの鋼材を要求します。2005 年より後の版では結果が異なることがあり、ワークブックとの照合は行っていません。",
  'flex.attribution': "CIRSOC 201-2005 の条項。独自の実装で、INTI-CIRSOC の CIRSOC_FLEX ワークブック（D. A. Ortega）の結果に対して検証しています。",
