  'whatsNew.title': "Stabileo {version}: 結果が変わった可能性があります",
  'whatsNew.body': "このバージョンでは、設計検定 (3D の CIRSOC 201 柱、EN 1992 曲げ、CIRSOC 301 圧縮、最小圧縮力下の RC 柱)、荷重ジェネレーター、座屈、調和解析と時刻歴解析、3D から 2D への切断、シェルの合成応力度における誤った結果を修正しました。それぞれに安全に関するお知らせ (SA-2026-025 から 047) があります。一部のモデルは、黙って解かれる代わりに、拒否または警告されるようになりました。2D の塑性崩壊は、修正が入るまで拒否されたままです。以前の結果に頼る前に、プロジェクトを再解析して設計検定を確認してください。",
