  'seismic.blocked.zone0': "表 3.1 は、地震ゾーン 0 のスペクトルを定義していません。2.5.2 条は、3 階建てまたは 12 m までの建物と、c1、c2、c3 を満たす風荷重で検定したそれより高い建物を、この規準の適用から除外しています。グループ Ao は決して除外されません。",
  'seismic.blocked.siteSF': "地盤種別 SF には、敷地固有の評価が必要です (2.3.2 条)。表 3.1 には読み取れる行がありません。",
  'seismic.assumed.faultProximity': "表 3.1 に記載された、断層近傍の最小値を採用しました: Na = {na}、Nv = {nv}。規準にはそれらを引き上げるための断層距離の表がありません。",
  'seismic.f1.garageSpecial': "表 3.1 はガレージに (*) を付けています: 同時性係数ではなく、全スペースが埋まった状態と実際の車両重量による荷重解析が必要です。",
  'seismic.derivation.weight': "W = D + f1·L + f2·S = {dead} + {f1}·{live} + {f2}·{snow} = {total} kN (式 3.15)。",
  'seismic.derivation.taOnly': "Ta = Cr·H^x = {cr}·{h}^{x} = {ta} s (式 6.8、表 6.2)。",
  'seismic.derivation.tComputed': "計算した周期 T = {computed} s を使います。これは Cu·Ta = {cu}·{ta} = {limit} s の上限を下回っています (式 6.7)。",
  'seismic.derivation.tCapped': "計算した周期 {computed} s は式 6.7 の上限を超えています: 代わりに Cu·Ta = {cu}·{ta} = {limit} s を使います。",
  'seismic.derivation.cPlateau': "T = {t} s ≤ T2 = {t2} s なので、C = 2.5·Ca·γr/R = {sa}·{gammaR}/{r} = {c} (式 6.3)。",
  'seismic.derivation.cSpectrum': "T = {t} s > T2 = {t2} s なので、C = Sa·γr/R = {sa}·{gammaR}/{r} = {c} (式 6.4)。",
  'seismic.derivation.cFloorNearFault': "ゾーン 3 と 4 に対する式 6.5 の下限が支配します: C = 0.8·as·Nv/R = 0.8·{as}·{nv}/{r} = {c}。",
  'seismic.derivation.cFloorLowZone': "ゾーン 0、1、2 に対する式 6.6 の下限が支配します: C = 0.11·Ca·γr = 0.11·{ca}·{gammaR} = {c}。",
  'seismic.derivation.dist': "Vo = {v0} kN を {levels} 層に Wk·hk / ΣWi·hi として分配します。ΣWi·hi = {sumWh} kN·m (式 6.11)。",
  'seismic.derivation.distTopHeavy': "T = {t} s は 2·T2 = {t2} s を超えています: Vo = {v0} kN の 90 % を Wk·hk (ΣWi·hi = {sumWh} kN·m) として {levels} 層に分配し、残りの 10 % は最上部の質量にすべて作用させます (式 6.12 と 6.13)。",
  'seismic.derivation.distNoMass': "基準レベルより上に質量がありません: 分配するものがありません。",
  'seismic.blocked.dynamicRequired': "2.7.3 条により動的解析法が必須です: T = {t} s は 3·T2 = {limit} s を超えています (T2 = {t2} s)。高さにかかわらず、静的解析法は適用できません。",
  'seismic.blocked.heightOverTable25': "表 2.5 は、ゾーン {zone} のグループ {group} について静的解析法を {limit} m までに制限しています。この建物の高さは {h} m です。",
  'seismic.blocked.irregular': "表 2.5 が静的解析法を認めるのは、平面にも立面にも整形な建物です。この建物は不整形と宣言されました。",
  'seismic.blocked.aoIrregular': "表 2.5 がグループ Ao に静的解析法を認めるのは、表 2.3 と 2.4 の 1a 行 (不整形なし) の場合のみです。この建物は中程度の不整形と宣言されました。",
