  'dsm.step2.whyTruss': "トラス部材: 軸力のみを受け持ちます。局所軸では軸方向の自由度に EA/L だけが現れ、横方向の行はゼロで、回転もありません。この部材は節点に回転剛性をまったく与えません。",
  'dsm.step2.whyHinge': "{end} 端のヒンジ: その端はモーメントを伝えないため、回転 θ{end} が縮約され、その行と列が消えます。部材は一端固定他端ピンの梁になります。12EI/L³ は 3EI/L³ に、{other} での回転剛性は 4EI/L から 3EI/L に下がり、伝達モーメント 2EI/L はなくなります。",
  'dsm.step2.whyBothHinged': "両端ピン: 部材はモーメントをまったく伝えず、曲げ剛性は [k] から消えます。残るのは EA/L だけで、トラス部材とまったく同じです。スパン内の荷重は、単純梁の反力として節点に伝わります。",
  'dsm.step2.whyReleases3d': "ここで解放されているもの: {list}。解放ごとにその回転が縮約され、行と列が消えます。その曲げ面では 12EI/L³ は 3EI/L³ に（反対端では 4EI/L が 3EI/L に）なります。ねじりを解放すると GJ/L のブロック全体がなくなります。",
