  'stress.panelTitle': "断面解析",
  'stress.close': "閉じる (Esc)",
  'stress.moveAlongElem': "部材に沿って移動 (x/L)",
  'stress.forces3dHelp': "この断面の 3D 断面力。\nN = 軸力 (+ 引張、- 圧縮)\nVy = XY 面内のせん断力 (Mz を生じる)\nVz = XZ 面内のせん断力 (My を生じる)",
  'stress.moments3dHelp': "Mx = ねじりモーメント\nMy = 局所 y 軸まわりのモーメント (せいの方向に曲げる、Iy を使用)\nMz = 局所 z 軸まわりのモーメント (幅の方向に曲げる、Iz を使用)\n回転していない縦長断面の既定: My が強軸 (鉛直)、Mz が弱軸 (水平)。断面を回転させるとこれらも断面とともに回転します。\n規約: + = 下側引張 (下縁が引張)",
  'stress.rotDecompHelp': "断面回転の分解 ({angle}°)。\nVy, Vz = 回転後の局所軸におけるせん断力成分",
  'stress.rotMomentHelp': "断面回転によるモーメント M の分解。\nMy = M·cos(α) (α=0 ではせい方向/強軸まわりの曲げ)\nMz = M·sin(α) (α=0 では幅方向/弱軸まわりの曲げ)\nα = {angle}°",
  'stress.forces2dHelp': "部材のこの断面における断面力。\nN = 軸力 (+ 引張、- 圧縮)\nV = 横せん断力\nM = 曲げモーメント (+ 下側引張)",
  'stress.criticalSections': "危険断面",
  'stress.criticalSectionsHelp': "部材に沿って応力度を検討すべき位置。\n\n最大モーメント (V=0) の点、支点、集中荷重の位置、中間点を含みます。\n各チップをクリックすると、その断面に移動します。",
  'stress.noGeomMsg1a': "断面 ",
  'stress.noGeomMsg1b': " の正確な輪郭がまだ用意されていないため、応力度分布、Mohr 円、破壊基準は計算できません。",
  'stress.cpInKern': "CC 内: σ は同符号",
  'stress.naOutside': "NA {arrow} 外側",
  'stress.rotSuffix': "(回転 {angle}°)",
  'stress.noGeomMsg2': "これはデータ不足による制約であり、断面の性質ではありません。断面自体は完全に定義されており、全体解析では公表値が通常どおり使われます。",
  'stress.noGeomMsg3': "MC を除くカタログのすべての系列で詳細解析に対応しています。それらのいずれかを割り当てるか、寸法を明示して断面を作成してください。",
  'stress.amorphMsg1': "選択した断面は<strong>任意形状</strong>です（幾何形状が定義されていません）。",
  'stress.amorphMsg2': "任意形状の断面は、応力度分布解析、Mohr 円、破壊基準に対応しません。",
  'stress.amorphMsg3': "断面解析を有効にするには、標準断面を割り当てるか、幾何形状を持つ断面を作成してください。",
  'stress.compositeMsg': "この断面は複数の材料を組み合わせています。その性能は換算断面のものであり、詳細な応力度場は単一材料に対して計算されるため表示されません。「結果」の部材応力度は各材料を考慮しています。",
  'stress.stressState': "応力状態",
  'stress.sigmaBiaxHelp': "2軸の垂直応力度 (Navier):\nσ = N/A − My·y/Iy + Mz·z/Iz\n\n正 = 引張 (赤)\n負 = 圧縮 (青)\n\n選択した繊維 (y, z) に依存します。",
  'stress.tauTotalHelp': "横せん断のみ、またはねじりせん断のみの大きさ。",
  'stress.combinedShearRefused': "ねじりせん断と横せん断が重なっています。合成応力度の結果は表示されません。",
  'stress.vonMisesHelp': "von Mises 基準 (ひずみエネルギー説):\nσvm = √(σ² + 3τ²)\n\n鋼や延性金属に適しています。\nパーセンテージは fy に対する使用率を示します。",
  'stress.trescaHelp': "Tresca 基準 (最大せん断応力度説):\nτmax = √((σ/2)² + τ²)\n\nvon Mises より約 15% 安全側。\n同等式: 2τmax ≤ fy",
  'stress.rankineHelp': "Rankine 基準 (最大垂直応力度説):\nmax(|σ₁|, |σ₃|) ≤ fy\n\n脆性材料 (コンクリート、岩石) に適しています。\n鋼には von Mises を推奨します。",
  'stress.neutralAxis': "中立軸:",
  'stress.neutralAxis3dHelp': "σ=0 となる合成中立軸。\n2軸曲げ (Mz と My) では、中立軸は斜めになることがあります。\nθ は Z 軸 (水平) からの角度です。",
  'stress.sigma2dHelp': "垂直応力度 (Navier の式):\nσ = N/A + M·y/I\n\n正 = 引張 (赤)\n負 = 圧縮 (青)\n\n選択した繊維 (y) に依存します。",
  'stress.tauMassiveHelp': "せん断応力度 (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = y より上の断面一次モーメント。\n中立軸で最大、自由縁でゼロ。\n長方形断面では放物線分布。\n\n仮定: τ は幅 b にわたって一様。\n幅の広い断面 (b ≈ h) では近似になります。\n実際の値は z 方向に変化します (中央で最大)。",
  'stress.tauThinHelp': "せん断応力度 (Jourawski):\nτ = V·Q(y) / (I·b)\n\nQ(y) = y より上の断面一次モーメント。\n中立軸で最大、自由縁でゼロ。\n\n薄肉断面では、τ が厚さにわたって\n一様であるという仮定は非常に精度が高い。",
  'stress.neutralAxisLabel': "(中立軸)",
  'stress.note2dTauOnly': "2D 解析: せん断力 V による τxy のみ",
  'stress.note2dNoTorsion': "ねじり (T=0) も面外せん断力 (Vz=0) もなし",
  'stress.neutralAxis2dHelp': "中立軸 (σ = 0):\ny_NA = -N·Iz / (A·M)\n\n垂直応力度がゼロになる位置。\n正 = 図心より上。\nN=0 のとき、NA は図心 (y=0) を通ります。",
  'stress.centralCore': "断面の核",
  'stress.centralCoreHelp': "CC は断面の幾何学的性質です。\nσ の符号が変わらずに N が作用できる範囲を定めます。\n断面上の CC ボタンを有効にすると表示されます。",
  'stress.ccDesc1': "<strong>断面の核</strong>は断面の幾何学的性質で、作用する荷重には依存しません。",
  'stress.ccDesc2': "垂直力 N が、垂直応力度 σ の符号を変えずに作用できる、図心まわりの領域を定めます。圧力中心が CC の内側にあれば、断面全体が純引張または純圧縮になります。",
  'stress.ccLimitZ': "水平軸方向",
  'stress.ccLimitY': "鉛直軸方向",
  'stress.ccEquations': "式",
  'stress.ccEqDesc': "図心から距離 <em>d</em> にある各縁繊維について、CC の頂点は次の位置にあります:",
  'stress.ccEqWhere': "ここで W = 断面係数、A = 断面積、I = 断面二次モーメント、d = 縁繊維までの距離。",
  'stress.sectionLabel': "断面:",
