  'stress.ccIHNote': "六角形: 頂点は (0, ±I<sub>z</sub>/(A·h/2)) と (±I<sub>y</sub>/(A·b/2), ±I<sub>z</sub>/(A·y<sub>web</sub>))",
  'stress.ccCHSNote': "半径 R<sub>cc</sub> = I<sub>z</sub>/(A·R) = R/4 の円（中実断面）",
  'stress.ccDefaultNote': "e<sub>y</sub> = I<sub>z</sub>/(A·y<sub>max</sub>)、e<sub>z</sub> = I<sub>y</sub>/(A·z<sub>max</sub>) のひし形",
  'stress.fiberY': "繊維 y:",
  'stress.fiberZ': "繊維 z:",
  'stress.fiberYZ3dHelp': "応力度を評価する断面の Y 軸と Z 軸上の位置。\nY (せい): My による曲げ、Iy を使用。Z (幅): Mz による曲げ、Iz を使用。\n回転していない既定の向きでは Y が強軸です。断面を回転させるとこれも回転します。\n黄色い点が選択した繊維を示します。",
  'stress.fiberY2dHelp': "応力度を評価する断面内の高さ。\ny = 0 は中心 (N=0 なら中立軸)。\nスライダーを動かすと、下縁から上縁まで走査できます。\n両端では垂直応力度が最大、せん断応力度が最小になります。",
