  'tour.modeToggleDesc': "<strong>Basic</strong> — 図、応力度、高度な機能を備えた 2D・3D の構造解析。<br/><strong>教育</strong> — 構造解析を学ぶためのステップごとの演習。<em>（開発中）</em><br/><strong>PRO</strong> — 建物全体の解析とレポート。規準に基づく設計は別途オンにする機能で、まだ開発中です。<br/><br/>このツアーは <strong>Basic</strong> モードで続きます。",
  'tour.buildOptionsTitle': "構造を作成する",
  'tour.buildOptionsDesc': "モデルを作る方法は3つあります:<br/><br/>&#x2022; <strong>ツール</strong> — ペイントのように、節点、部材、支点、荷重を描く<br/>&#x2022; <strong>右側のパネル</strong> — 数値データを直接入力する<br/>&#x2022; <strong>用意された例題</strong> — 最も手早く始められる方法<br/><br/>まずは例題から始めることをおすすめします。進みましょう &#x2192;",
  'tour.examplesTitle': "例題を読み込む",
  'tour.examplesDesc3D': "どれかの例題を選ぶと、すぐに読み込まれます。<br/><br/>Stabileo 2D にあるモデルはすべて（トラスを除いて）解析できます。<br/><br/>3つの次元を活かせる <strong>3D 例題</strong>もあります。<br/><br/>または、下のボタンでおすすめの例題を読み込めます。",
  'tour.examplesDesc2D': "どれかの例題を選ぶと、すぐに読み込まれます。<br/><br/>または、下のボタンでおすすめの例題を読み込めます。",
  'tour.examplesBtn3D': "3D ラーメン",
  'tour.examplesBtn2D': "ラーメンの例",
  'tour.manualToolsTitle': "手動で作成",
  'tour.manualToolsIntro': "すべてを手作業で作りたい場合は、次の順に進めてください:",
  'tour.manualToolsNode': "節点",
  'tour.manualToolsNodeDesc': "キャンバス上に点を配置",
  'tour.manualToolsElement': "部材",
  'tour.manualToolsElementDesc': "2つの節点を部材でつなぐ",
  'tour.manualToolsSupport': "支点",
  'tour.manualToolsSupportDesc': "節点の動きを拘束",
  'tour.manualToolsLoad': "荷重",
  'tour.manualToolsLoadDesc': "力や分布荷重を載荷",
  'tour.manualToolsMaterials': "右側のパネルから<strong>材料</strong>と<strong>断面</strong>も変更できます。",
  'tour.rightPanelTitle': "右側のパネル",
  'tour.rightPanelDesc': "ここでモデルのデータをすべて表示・編集できます:<br/><br/>&#x2022; <strong>節点</strong> — 各点の座標<br/>&#x2022; <strong>部材</strong> — 材料と断面を持つ部材<br/>&#x2022; <strong>材料</strong> — E、ν、fy などの特性<br/>&#x2022; <strong>断面</strong> — 市販の断面を選ぶか、独自の断面を作成<br/>&#x2022; <strong>支点</strong> — 各支点のタイプと拘束<br/>&#x2022; <strong>荷重</strong> — 載荷した力と分布荷重<br/>&#x2022; <strong>組合せ</strong> — 荷重組合せ<br/>&#x2022; <strong>結果</strong> — 解析後に表示<br/><br/>任意の欄をクリックすると、直接編集できます。",
  'tour.solveTitle': "解析しましょう",
  'tour.solveDesc': "構造に節点、部材、支点、そして1つ以上の荷重がそろったら、<strong>計算</strong>を押します。<br/><br/><strong>直接剛性法</strong>で解析します。<br/><br/>下のボタン、またはサイドバーのボタンを使ってください。",
  'tour.solveBtn': "計算",
  'tour.resultsTitle': "結果",
  'tour.resultsDesc': "ここで解析結果を確認できます:<br/><br/><strong>変形図</strong> — 拡大した構造の変形図<br/><strong>モーメント / せん断力 / 軸力</strong> — 各部材の代表的な断面力図<br/><strong>軸力の色</strong> — 引張（赤）と圧縮（青）。トラスに便利<br/><strong>カラーマップ</strong> — 各断面力の大きさに応じたヒートマップ<br/><br/>切り替えて確認してみてください。",
  'tour.navigateTitle': "モデルを操作する",
  'tour.navigateDescMobile': "2本の指で<strong>パン</strong>と<strong>ズーム</strong>ができます。<br/><br/>右上の<strong>フィット</strong>アイコンをタップすると、モデルを画面に合わせられます。<br/><br/>左上の <strong>📊</strong> ボタンを押すと、結果と図を表示するフローティングパネルが開きます。",
  'tour.navigateDescDesktop': "<strong>パン</strong>ツールでは、マウスをドラッグしてキャンバス上を移動します。<br/>スクロールホイールでズームします。<br/><br/>右上の<strong>フィット</strong>アイコンをクリックすると、モデルを画面に合わせられます。",
  'tour.navigateDesc3DExtra': "そのオプションの下には、プリセットビュー（上面、正面、側面）、透視/平行投影、クリッピング平面、計測などのツールがあります。",
  'tour.queryResultsTitle': "任意の点の結果",
  'tour.queryResultsDescMobile': "<strong>応力度</strong>モードで <strong>↖ 選択</strong>ツールを有効にすると、部材をタップしたときの断面力が表示されます。<br/><br/>または、図の近くに指を近づけるだけで、その点の値を確認できます。",
  'tour.queryResultsDescDesktop': "<strong>応力度</strong>モードで<strong>選択</strong>ツールを有効にすると、部材をクリックしたときの断面力がすべて表示されます。<br/><br/>または、図の近くにマウスを近づけるだけで、その点の値を確認できます。",
  'tour.advancedTitle': "高度な解析",
  'tour.advancedDesc': "基本的な部材解析の先に進むためのツールです。<br/><br/>各ツールの右にある <strong>(?)</strong> をクリックすると、その内容を確認できます。",
  'tour.advancedDesc3DExtra': "補足として、現時点では Stabileo 2D のほうがはるかに多くの高度な機能を備えています。",
  'tour.advancedDescBeta': "これらの機能はまだ開発中であることにご留意ください。不具合の報告をお待ちしています。",
  'tour.peek3dTitle': "3D で見る",
  'tour.peek3dDesc': "2D で解析したのと同じ構造が、<strong>3D モード</strong>でも使えます。<br/><br/>マウス（モバイルでは2本の指）でモデルを回転させ、あらゆる角度から確認できます。<br/><br/>図、変形図、応力度解析もすべて 3D で利用できます。<br/><br/>準備ができたら「次へ」を押して 2D に戻ります。",
  'tour.configProjectTitle': "設定とプロジェクト",
  'tour.configProjectDesc': "<strong>設定</strong> — 表示オプション: グリッド、ラベル、単位、そして<strong>ライブ計算</strong>（構造を編集すると自動的に再計算）。<br/><br/><strong>プロジェクト</strong> — 作業を保存し、誰でも構造を見られるリンクを共有し、レポート（Excel、PDF、PNG、CSV）をエクスポートします。<br/><br/>DXF と SVG のインポート/エクスポートツールは開発中です。",
  'tour.feedbackTitle': "不具合の報告・改善の提案",
  'tour.feedbackDesc': "エラーを見つけた、またはアイデアがありますか？<br/>このボタンを押して報告を送ってください。<br/><br/>問題を再現できるように、現在のモデルの状態が自動的に添付されます。",
  'tour.goodbyeTitle': "Stabileo をご利用いただきありがとうございます :)",
  'tour.goodbyeDesc': "構造の学習や解析のお役に立てば幸いです。<br/><br/>気に入っていただけたら、同僚や友人にリンクを共有してください。<br/><br/><em style=\"color:#4ecdc4; font-style:normal\">Bauti</em>",
