  'svc.magnitudeNonlinear': "一方向部材、浮き上がり支点、または支点曲線を持つモデルでは SRSS と ABS の荷重組合せは解けません：荷重ケースが足し合わせられないためです。線形に設定するか、削除してください：{names}。",
  'svc.spectralNonlinear': "スペクトルケースを含む荷重組合せは、一方向部材、浮き上がり支点、または支点曲線を持つモデルでは解けません：スペクトル部分は線形で、非線形状態に加えることができないためです。それらからスペクトルケースを外すか、荷重組合せを削除してください：{names}。",
