  'svc.torsionGap.shearCentre': "断面 {section} はせん断中心が不明な T 形、溝形または山形で、{analysis}ではこのような断面で支配的となる部材 {members} の曲げねじり座屈を扱えません。せん断中心が計算されるよう、断面に形状（寸法または輪郭）を与えてください。",
