  'wb.cover.case': "ケース",
  'wb.conv.axes': "全体軸：X と Y は水平、Z は上向き、右手系。変位と反力は全体軸で示します。",
  'wb.conv.localAxes': "部材の局所軸：x は節点 I から節点 J へ向かい、y と z は局所 Y ベクトルとロール角に従います。エクスポートされるロール角は、部材のロールと断面の回転の両方を含み、単位は度です。",
  'wb.conv.sources': "結果の出典：case と combination は、解いた荷重ケースまたは荷重組合せを示します。Single（sourceId 0）は単独の解析で、個別の荷重ケースではありません。包絡線のエクスポートは出典に envelope、id に 0 を使い、表示中の包絡線名を付けます。Magnitude は SRSS または ABS による荷重組合せで、値は符号のない大きさであり、釣合いを満たさず、最大値と包絡線には含まれません。",
  'wb.conv.selfWeight': "SelfWeight レコードには方向、係数、適用範囲が入ります。別の旧式の単独行がその重力を定義していない限り、ケースの規則は全荷重の解析にも適用されます。旧式のケース行と単独行は択一であり、加算されません。ケースの規則と旧式の単独重力はインポートされ、未対応の適用範囲は報告されます。",
  'wb.conv.selfWeightImport': "SelfWeight レコードには方向、係数、適用範囲が入ります。別の旧式の単独行がその重力を定義していない限り、ケースの規則は全荷重の解析にも適用されます。旧式のケース行と単独行は択一であり、加算されません。ケースの規則と旧式の単独重力はインポートされ、未対応の適用範囲は報告されます。",
  'wb.conv.units': "すべて SI 単位：m、kN、kN·m。部材の応力度と係数は MPa、シェルの応力度は kN/m²、シェルのモーメントは kN·m/m で、画面の表示どおりです。回転は rad、温度は °C です。各見出しの括弧内に単位があります。",
  'wb.conv.displacements': "変位：各節点の並進 ux、uy、uz と、X、Y、Z まわりの回転を、解析結果のまま示します。",
  'wb.conv.reactions': "反力：支点が構造に及ぼす力とモーメントを全体軸で示します。作用荷重とつり合います。",
  'wb.conv.memberForces': "部材の断面力は局所軸で、解析の符号に従います。これは画面の図が示す符号と同じです。N は引張が正で、Vy、Vz、T、My、Mz は図に描かれるとおりです。",
  'wb.conv.stations': "着目点：各部材に沿った点で、x は節点 I から測ります。最初と最後は部材端で、そこでの着目点の断面力は材端力に等しくなります。",
  'wb.conv.deflections': "たわみ：各着目点の変位を、変位後の部材端を結ぶ弦に対して、局所 y（v）と z（w）およびその合成で示します。",
  'wb.conv.stresses': "応力度：各着目点の断面における最大と最小の垂直応力度で、引張が正です。基準 \"geometry\" は断面の輪郭を、\"bounds\" は外接長方形を読み取ります。",
  'wb.conv.shells': "シェル、各要素の中心：要素の局所軸（x は第1辺に沿い、z はそれに垂直）での膜応力度 σxx、σyy、τxy とモーメント mx、my、mxy、および MITC4 四角形では面外せん断力 qx、qy。全体の列は、同じ応力度・モーメント・せん断力を全体軸に変換したもので、曲面の四角形にはありません。",
  'wb.conv.shellFaces': "シェルの面：膜応力に 6M/t² を加えた値（上面、局所 z に沿って z = +t/2）と減じた値（下面）で、それぞれ主応力度 σ1、σ2、局所 x から σ1 までの角度、Von Mises、Tresca（σ3 = 0 として）を示します。膜応力のみの値もあります。曲面シェルには曲げモーメントや面の応力度の復元値がなく、そのセルは空欄で、最大値からも除外されます。厚さが欠けているか無効な場合も、面のセルは空欄になります。",
  'wb.conv.shellNodes': "シェル節点：各節点の周囲の要素の平均を全体座標系の成分で示します。シェルの隅角：各要素の隅角での Von Mises 応力度を、エンジンの報告どおりに示します。三角形では不利な側の面、四角形では膜応力のものです。",
  'wb.conv.envelope': "包絡線：節点、部材端、成分ごとに、荷重組合せ全体（組合せがなければ荷重ケース全体）での最大値と最小値を、それを生じる組合せとともに示します。",
  'wb.conv.maxima': "最大値：成分ごとに、全体での最大値と最小値、その発生位置、および発生した荷重組合せを示します。部材の断面力は着目点で読み取ります。",
  'wb.conv.statics': "静力学：ケースと荷重組合せごとに、作用荷重の合力、反力の合力、それらの全体原点まわりの和を示します。worstRelative は、荷重に対する残差の最大の比です。",
  'wb.conv.secondOrder': "二次解析：P-Δ効果を考慮して解いた荷重組合せ。二次の釣合いが成立しない荷重組合せ（荷重に達する前に構造が座屈する）は結果行がなく、ここに挙げられます。",
  'wb.conv.oneWay': "一方向部材と浮き上がり支点：各結果のアクティブセット解析で、緩んだ部材と浮き上がった支点を示します。",
  'wb.conv.model': "モデルのシートは、インポート側のシート名と列キーを使うため、読み戻せます。インポート側が認識しない列は読み飛ばされます。断面性能はエンジンに渡された値です。",
  'wb.conv.text': "テキストのセルは、スプレッドシートが数式と見なす +、-、=、@ で始まりません。先頭のマイナスはマイナス記号（−）で書かれます。",
  'wb.conv.precision': "数値は全桁で書き出されます。xlsx ファイルに収まらない大きさのブックや、400万セルを超えるブックは、シートごとに CSV を1つ入れた zip で書き出されます。",
