  'defl.note': "δ は、たわんだ部材から、そのスパンの変位後の両端を結ぶ弦までの距離です。節点の変位ではなく、部材自身の曲げによるものです。片持ち梁では付け根の接線までの距離です。スパンは物理的な部材で、それを分割している同一直線上の要素（スラブのメッシュ、分割、荷重による）はまとめて測り、支点、拘束、またはそれを支えられる部材だけがスパンを区切ります。δy と δz はその局所平面内の成分です。δ/L の大きい順に並べています。",
