  'fx.note.aciDetailing': "鉄筋の納まり、ひび割れ制御の間隔、帯筋、最小・最大鉄筋量およびかぶりを対応づけています。定着長さは対応づけていません（CIRSOC 201-2025 25.4.3.1 はフック付きの長さを db に線形としますが、ACI 318-19 は db^1.5 とします）",
