  'memo.glob.softBasis': "剛性テストによって提案されたソフトストーリー（上階の 70 % 未満、または上の 3 層の平均の 80 % 未満）。層間変形を比較する INPRES-CIRSOC 103 第 I 部 2018 の表 2.4 ではありません。",
  'detailing.clash.unresolved': "干渉が未解決 — 鉄筋 {bar} と {barB}、要素 {element}：あきが {shortfall} mm 不足。{rungs} 段階の修正で {tried} 回の移動を試み、すべて却下：断面からの逸脱 {outside} 件（最大 {outsideBy} mm）、検証済みの有効せいの低下 {depth} 件（最大 {depthBy} mm）、他の鉄筋のあきへの侵入 {clearance} 件",
  'check.detailing.clash': "調整後の鉄筋のあき",
  'check.design.refused': "検定を満たす配筋のない設計",
  'defl.checkHintTable': "各部材の規則が制限するたわみの検定比。コンクリートでは CIRSOC 201 表 24.2.2 による：L/360（屋根は L/180）では積載荷重による即時たわみ、L/480 または L/240 では非構造部材の取付け後の分（持続荷重の長期たわみに積載荷重を加えたもの）、それ以外の制限では長期たわみの合計。鋼では長期の増幅係数は用いません。設計と同じ検定です。",
  'design.reason.alternativesExhausted': "要素 {elementId}：探索が実装する配置のいずれも検定を満たしません（候補 {tried} 件：鉄筋 Ø{diameters} mm を最大 {rows} 段、領域ごとに最初の {options} 案、あばら筋 Ø{stirrups} mm を最大 {legs} 本脚）。支配要因：{limiting}。これは断面に配筋できないことを示すものではありません。",
  'design.reason.exhaustedBudget': "要素 {elementId}：予算により、候補 {tried} 件で探索を停止しました（鉄筋 Ø{diameters} mm を最大 {rows} 段、あばら筋 Ø{stirrups} mm）。支配要因：{limiting}。",
