  'design.gap.headedBars': "未試行：頭付き鉄筋（§25.4.4）。フックが納まらない箇所でも定着できます。",
  'design.gap.mechanicalAnchorage': "未試行：機械式定着の鉄筋（§25.4.5）。",
  'design.gap.columnCageChange': "未試行：柱の鉄筋かごの鉄筋の変更。設計では設計済みのものとして扱います。",
  'design.reason.insufficiency.shearSectionLimit': "要素 {elementId}：{axis} 方向の Vu = {demand} {unit} が φ·(Vc + 0.66·√f′c·bw·d) = {capacity} {unit} を超えます（§22.5.1.2）。Vc は上限 0.42·√f′c·bw·d（§22.5.5.1.1）、bw = {bw} m、許容される鉄筋が与える最大の d = {dMax} m とします。配筋ではこの限界を引き上げられません：断面が不足しています。",
  'design.reason.insufficiency.axialCapacityAtMaxSteel': "要素 {elementId}：Pu = {demand} {unit} が {capacity} {unit} を超えます。これは §10.6.1.1 が認める最大鉄筋量（ρ = {rho}）とスパイラルの係数（φ = {phi}、{poFactor}·Po）による表 22.4.2.1 の軸耐力です。配筋ではこの限界を引き上げられません：断面が不足しています。",
  'design.reason.insufficiency.minimumBarRowDoesNotFit': "要素 {elementId}：最小あきを確保した Ø{barDiameterMm} の鉄筋 2 本には {demand} {unit} が必要ですが、最小のあばら筋（Ø{stirrupDiameterMm}）の内側には {capacity} {unit} しかありません（§{clause}）。許容されるどの鉄筋配置も納まりません：断面が不足しています。",
