  'notice.D006.fix': "支配的な検定と未試行の代替案を確認し、そのうちの 1 つで部材を手作業で設計するか、断面または取り付く部材を変更してください。",
  'check.design.sectionInadequate': "断面が不足：配筋では引き上げられない規準の限界",
  'check.design.alternativesExhausted': "検定を満たす実装済みの配置なし",
  'detailing.convergence.exhausted': "検定を満たす実装済みの配置がない部材が {n} 件あります。各部材の理由を参照してください：{ids}",
  'lateral.symbol': "水平力抵抗システム",
  'lateral.title': "水平力抵抗システム",
  'lateral.projectHint': "CIRSOC 201-2025 §9.7.3.8.2：システムの一部である梁の下端筋は、支持面で fy を発揮できるよう定着し、そうでない梁の下端筋は支持部に 150 mm 入れます。宣言されていない梁は、システムの一部として設計されます。各梁は設計デスクで宣言でき、その宣言がこの設定に優先します。",
