  'lateral.reading.lateral': "システムの一部と宣言済み：下端筋は支持面で fy を発揮できるよう定着されます（§9.7.3.8.2）。",
  'lateral.reading.gravity': "システム外と宣言済み：下端筋は支持部に 150 mm 入ります（§9.7.3.8.1 と §9.7.3.8.2）。",
  'lateral.reading.undeclared': "未宣言：システムの一部として設計され、下端筋は支持面で fy を発揮できるよう定着されます。これは 150 mm の要件（§9.7.3.8.2）も満たします。適切な解釈を適用するには宣言してください。",
