  'lateral.withdraw': "階の宣言を取り消す",
  'lateral.beamUndeclared': "梁 {id}：未宣言、主梁として検定。形状からは {suggested} が提案されます",
  'lateral.seismicAssumed': "{role}、未宣言：主梁として検定",
  'lateral.rolesHint': "各梁の役割はプロジェクトが宣言したものです。水平力抵抗システムの一部であれば主梁、そうでなければ小梁です。宣言されていない梁は主梁として検定され、破線で描かれます。形状から役割が提案され（両端で柱または壁に達する線は主梁）、採用できます。梁をクリックすると、もう一方の役割を宣言できます。",
  'advanced.offsetsUnsupported': "モデルには偏心（部材の挿入点またはシェルのオフセット）が宣言されており、この解析は節点を結ぶ線上で解かれます。中心位置の結果をモデルの結果として示さないよう、実行しません。静的解析と荷重組合せには偏心が含まれます。",
  'detailing.lapCheck.unarranged': "{joint} の重ね継手が未配置：鉄筋 {bar} と {barB}（Ø{diameter}）が同じ中心線上にあり、{offset} mm 離れています（接触する 2 本では {contact} mm）。{pairs} 組。並べてずらす方法も、それらを分けるクランクもモデル化されていないため、隣接する鉄筋との重ね継手のあきは検定されていません（§25.5.1.2）。",
  'detailing.lapCheck.pitch': "{joint} の非接触重ね継手：鉄筋 {bar} と {barB} は中心間で {offset} mm 離れており、必要重ね長さ（{lap} mm）の 1/5 と 150 mm の小さい方である {limit} mm を超えています（§25.5.1.3）。{pairs} 組。",
  'detailing.lapCheck.short': "{joint} の重ね継手が短すぎます：鉄筋 {bar} と {barB}（Ø{diameter}）の重ねは {overlap} mm で、必要なのは {required} mm です。ℓd = {ld} mm、ψt = {psiT} に基づく B 級（表 25.5.2.1 と §25.5.2.2）。{pairs} 組。",
  'detailing.lapCheck.barTooLarge': "{joint} では重ね継手は認められません：鉄筋 {bar} と {barB} は Ø{diameter} で Ø{limit} より大きく、重ね継手にはできません（§25.5.1.1）。",
  'detailing.lapCheck.ktr': "{joint} の重ね継手は未検証：fy = {fy} MPa で {limit} MPa を超えるため、{bar} と {barB} の重ね継手には、その全長にわたって Ktr ≥ 0.5 db の横補強筋が必要です（§25.5.1.5）。Ktr は計算されていません。",
  'detailing.lapCheck.seismic': "耐震プロジェクトの {joint} における重ね継手は未検証：プロジェクトは INPRES-CIRSOC 103 を適用しており、{bar} と {barB} の重ね継手は塑性ヒンジが生じ得る部材端にあります（§2.2.10.1 と §2.3.13.1）。その位置は検証されていません。",
  'detailing.lapCheck.spacing': "{joint} の重ね継手が過密：{bar} と {barB} のあきは {clear} mm で、§25.5.1.2 が重ね継手と隣接する鉄筋の間に求める §25.2.3 の {required} mm より小さくなっています。",
  'detailing.lapCheck.noPartner': "{joint} に重ね継手のない鉄筋：{bar}（Ø{diameter}）は床から始まり、下に重ねる鉄筋がありません。",
  'detailing.lapCheck.integrity': "{joint} でインテグリティ鉄筋が継がれています：外周梁で上端筋 {laps} 本が支持部上で重ね継手となり、{continuous} 本が連続して通っています（{supportArea} mm² のうち {continuousArea} mm²）。負曲げモーメントのインテグリティ鉄筋はスパン中央またはその付近で継ぎ（§9.7.7.5(b)）、少なくとも 2 本かつ上端筋の 6 分の 1 を連続させる必要があります（§9.7.7.1(b)）。",
