  'detailing.joint.assumedJd': "内部の弾性的なてこの腕を jd = {ratio} d としています。§15.4.1.1 は曲げによって生じる引張力と圧縮力を求めることを要求していますが、jd の求め方は定めていません。この値は長方形断面で一般的なものであり、規準上の値ではありません。",
