  'detailing.joint.unsupported.biaxial': "平面の両方向に梁がある接合部です。2 軸の検定では、各方向のせん断をそれぞれの Aj で設定し、その影響を組み合わせる必要がありますが、実装されていません。接合部のせん断は未検証です。",
  'detailing.joint.unsupported.equilibriumResidual': "接合部の自由体が閉じていません。最大の寄与力に対する平衡残差は {residual} % で、制限値は {limit} % です。接合部のせん断は未検証です。閉じていない自由体から得られた結果は検証ではありません。",
  'detailing.joint.memo.freeBody': "接合部の中間高さでの自由体（§15.4.1.1）: {tensions}、Vcol = {columnShear} kN → Vu = {vu} kN。",
