  'detailing.transverse.slabNoneRequired': "せん断補強筋は不要です: v_u = {vu} kN/m、φv_c = {phiVc} kN/m（§7.6.3.1）。",
  'detailing.transverse.slabShearReinforcementNeeded': "せん断補強筋が必要です — v_u = {vu} kN/m が φv_c = {phiVc} kN/m を超えています — が、スラブでのその算定は実装されていません。",
  'detailing.transverse.wallNoTiesRequired': "帯筋は不要です: 鉛直方向の鉄筋比 ρ_l = {rho} は、§11.7.4.1 の 0.01 を下回っています。",
