  'footing.ui.matPunchingMoment.NEGLIGIBLE': "接合部での不釣合いモーメント Msc = {msc} kN·m（成分 {x} と {y}）は、有意性のしきい値 {threshold} kN·m を下回っています。直接せん断が支配します。これは §8.4.4.2 の検証ではありません。",
  'footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_TRANSFER_NOT_EVALUATED': "押抜きは未検証です。接合部は不釣合いモーメント Msc = {msc} kN·m（成分 {x} と {y}）を伝達しており、しきい値 {threshold} kN·m を上回っていますが、§8.4.4.2 の偏心せん断によるモーメント伝達は実装されていません。下端マットは検証済みですが、基礎全体は検証されていません。",
  'footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_NOT_FORMED': "押抜きは未検証です。接合部の不釣合いモーメントを求められなかったため、ゼロであるとは主張しません。直接せん断だけを検定すると、モーメントを誰も評価していない接合部を合格させてしまいます。",
  'footing.ui.matGeometrySteps': "形状のメモ",
  'footing.ui.matAnchorageSteps': "定着のメモ",
  'footing.record.flexureGeometryNotReconciled': "下端マットは設計済みですが、その物理的な形状が鉄筋表と整合しません。重大な所見が {findings} 件あります。承認された鉄筋表と食い違うマットを描画すると、誰も設計していない配筋を記述したものがモデル、図面、エクスポートに到達してしまうため、鉄筋は出力されません。曲げは未検証です。",
  'footing.record.anchorageNotEvaluated': "測定すべき物理的なマットがないため、下端鉄筋の定着は評価されていません。これは定着の不適合ではなく、測定の基となる形状がないということです。",
  'footing.record.topReinforcementNotEvaluated': "基礎 {footing}: 上端筋は評価されていません。このプロジェクトには上端筋が不要であることを示す信頼できる計算がないため、不要とは主張せず、上端筋の設計も行いません。下端マットの検証は有効ですが、これが未解決のままの間は、この基礎は発行に適しません。",
  'footing.geometry.noLayerOrder': "物理的な層の順序が確定していない（{rationale}）ため、鉄筋を描く高さがありません。安全側の包絡線の深さで描画すると、誰も選んでいない高さの鋼材をモデルに置くことになります。",
  'footing.geometry.directionNotDesigned': "{axis} 方向は設計されていない（{status}）ため、どちらの方向にも形状は生成されません。§13.3.3 は両方向の配筋を要求しており、半分のマットはマットではありません。",
  'footing.geometry.elevationMismatch': "{axis} 方向: 鉄筋軸の高さは有効せい {implied} m を意味しますが、設計は {designed} m で行われています。鉄筋は設計時とは異なる深さに描かれることになります。",
  'footing.geometry.countMismatch': "{axis} 方向、領域 {region}: 鉄筋表では {scheduled} 本が求められていますが、配置では {placed} 本になりました。図面を合わせるために鋼材を再配分することはしません。",
  'footing.geometry.spacingMismatch': "{axis} 方向、領域 {region}: 配置されたピッチは {placed} mm で、鉄筋表のピッチは {scheduled} mm です。",
  'footing.geometry.sideCoverShort': "{axis} 方向、領域 {region}、鉄筋 {bar}: 鉄筋の表面まで測った側面のかぶりは {measured} mm で、必要な {required} mm を下回っています。",
  'footing.geometry.bottomCoverShort': "{axis} 方向、鉄筋 {bar}: 表面まで測った下面のかぶりは {measured} mm で、必要な {required} mm に対して不足しており、上面まで {toTop} mm 残っています。",
