  'footing.geometry.duplicateBar': "{axis} 方向: 鉄筋 {a} と {b} が同じ位置にあります。",
  'footing.geometry.clearSpacingShort': "{axis} 方向: 鉄筋 {a} と {b} の間のあきは {measured} mm で、§25.2.1 の {required} mm を下回っています。これは隣り合う §13.3.3.3 の領域の間の隙間で、単一の領域では配置されません。",
  'footing.geometry.providedAsMismatch': "{axis} 方向: 生成された鉄筋の断面積は {placed} cm² ですが、鉄筋表には {scheduled} cm² と記載されています。",
  'footing.anchorage.insufficient': "{axis} 方向、Ø{diameter}: 直線定着で {required} mm が必要ですが、柱面から鉄筋の物理的な端までの利用可能な長さは {side} 側で {available} mm で、{short} mm 不足しています。フックは考案せず、ld も低減しません。",
  'footing.anchorage.noGeometry': "物理的なマットがない（{status}）ため、危険断面から利用できる長さを測定できません。",
  'footing.record.flexureDesignedNotModeled': "下端マットは両方向とも設計済み（断面力、必要鋼材量、本数、規準に適合するピッチ）ですが、モデル化されていません。物理的な鉄筋は、モデル、鉄筋表、CAD への引き渡しのいずれにも存在しません。そのため、断面力を検証する配筋がまだないので、曲げは未検証のままです。",
