  'footing.migration.layerOrderToAuto': "どちらの下端マットが下の層に入るかがプロジェクトに記載されていなかったため、層の順序は自動として読み込まれました。これは前のバージョンに対して設計を変更します。以前は両方向とも浅い方の有効せい（安全側の包絡線）で設計されていましたが、今は各方向が実際の深さで設計されます。順序は「基礎」で手動で固定できます。",
