  'footing.cad.assembly.description': "基礎を支持する柱とつなぐ柱のダボ筋と差し筋の帯筋です。基礎のマットの形状は含まれません。",
  'footing.cad.family.columnDowel': "基礎と柱の境界面で柱の力を伝える柱のダボ筋。",
  'footing.cad.family.starterTie': "基礎の上の重ね部分でダボ筋を拘束する差し筋の帯筋。",
  'footing.cad.interface.intentionalPassage': "これらの鉄筋は、基礎と柱の境界面を意図的に横切っています。この交差は設計どおりの詳細であり、拘束やかぶりの不適合として報告してはなりません。",
  'footing.cad.derivation.columnStub': "要素 {element} の柱スタブ: 要素の断面から平面 {B} × {L} m、基礎上面 z = {base} m から z = {top} m まで。上の面は実際の伝達かごの上端（{cageTop} m）で、柱頭（{columnTop} m）を超えないよう切り詰められています。",
  'footing.cad.cover.placementIntent': "モデルが保持する基礎のかぶり。これは鉄筋を配置するための入力値であり、測定または検証された実際のかぶりではありません。",
  'footing.cad.check.collision': "鉄筋同士の干渉。実際の衝突検出器によるものです。",
  'footing.cad.check.clearSpacing': "鉄筋のあき。実際の衝突検出器によるものです。",
  'footing.cad.check.footingCover': "基礎内部のコンクリートのかぶり。",
  'footing.cad.check.columnCover': "柱スタブ内部のコンクリートのかぶり。",
  'footing.cad.check.containment': "配筋が基礎のコンクリートの内側にあるかどうか。",
  'footing.cad.notEvaluated.footingCover': "基礎 {footing}: Stabileo は実際に得られたかぶりを測定しません。かぶりは配置の入力値であり、得られた形状を検査する実際のコードの経路はないため、報告すべきかぶりの判定はありません。",
  'footing.cad.notEvaluated.columnCover': "要素 {element}: 柱のかぶりは、このリリースの対象外です。基礎のかぶりの値は柱スタブには適用されず、それに対して測定してはなりません。",
  'footing.cad.notEvaluated.containment': "基礎 {footing}: Stabileo には、どの要素の種類に対しても、実際の幾何学的な包含検査がないため、包含は評価されません。",
  'footing.cad.unsupported.matGeometry': "基礎 {footing}: 下端と上端のマットは図面上の要件であり、鉄筋の形状ではありません。この引き渡しには柱の伝達かごのみが含まれ、基礎の完全な配筋ではありません。",
  'footing.cad.unsupported.containment': "基礎 {footing}: 配筋の包含は Stabileo では評価されません。外部での測定は独立した観察であり、Stabileo の判定になることはありません。",
  'footing.cad.unsupported.columnCover': "要素 {element}: 柱のかぶりは、ここでは要求も評価もされません。",
  'footing.cad.assumption.stubTruncated': "要素 {element} の柱スタブは、伝達かごの上端である z = {top} m で切り詰められています。その上の面はコンクリート表面ではなく切断面であり、それに対してかぶりは測定できません。",
  'footing.cad.assumption.sampler': "鉄筋の範囲と境界面での交差は、衝突検出器と同じ経路である、円弧に対応した実際の中心線サンプラーで、弦の許容差 {tolerance} mm で測定しました。",
  'footing.cad.assumption.columnBaseAbove': "解析モデルでは、柱要素 {element} の下端節点は z = {base} m にあり、基礎上面 z = {top} m より {gap} m 上にあります。実際のダボ筋と差し筋の形状はその高さを基準に配置されたため、スタブは基礎上面から取っています。",
  'footing.cad.assumption.aggregate': "プロジェクトのどのコンクリートにも粗骨材の最大寸法が記載されていないため、{mm} mm と仮定します。これは規準の既定値ではありません。",
  'footing.cad.refusal.footingNotFound': "ID {id} の基礎がありません。",
  'footing.cad.refusal.nodeNotFound': "基礎 {footing} は節点 {node} を参照していますが、モデルにありません。",
  'footing.cad.refusal.noColumn': "基礎 {footing} は柱を参照していません。柱がなければ、平面の範囲も境界面もなく、柱の寸法を作り上げると誰かの基礎を動かしてしまいます。",
  'footing.cad.refusal.notDimensioned': "基礎 {footing} は寸法が定まっていません。平面寸法と厚さはすべて正である必要があります。",
  'footing.cad.refusal.rotated': "基礎 {footing} は {rotation}° 回転しています。接合部を回転した基礎の軸に分解する処理は実装されておらず、全体座標軸を局所軸として扱うと境界面の位置がずれます。",
  'footing.cad.refusal.eccentric': "基礎 {footing} には平面の偏心 ({b}, {l}) m があります。モデルはこれを基礎の図心のずれとして記録していますが、実際のダボ筋の形状はこれを柱の中心として使っています。値がゼロでない場合、それらは別の場所になり、どちらかを選ぶのは推測になります。",
  'footing.cad.refusal.pedestal': "基礎 {footing} には柱脚があります。柱脚は固有の境界面を持つ 3 つ目のコンクリート部材であり、このリリースでは表現されません。",
  'footing.cad.refusal.noAssembly': "基礎 {footing} には詳細設計の組立がありません。先に基礎の詳細設計を生成してください。",
  'footing.cad.refusal.noVerifier': "基礎 {footing} には検証者の識別情報がありません。引き渡しの証明書に検証者が記載されず、受け取る側は、それを伝達中に失われたものと区別できません。規準による検定と設計を実行して部材を検証し、詳細設計を再生成してください。その実行後にプロジェクトの規準が変更された場合、以前の識別情報はもはや適用されないため、現在設定されている規準で設計をやり直す必要があります。",
  'footing.cad.refusal.noCage': "基礎 {footing} の組立には、伝達かごの配筋がありません。",
  'footing.cad.refusal.noDowels': "基礎 {footing} には柱のダボ筋がないため、エクスポートする伝達かごがありません。",
  'footing.cad.refusal.unclassifiedBar': "基礎 {footing}: これらの鉄筋には、このエクスポーターが示せる配筋の種別がありません — {bars}。既存の種別に割り当てると、誤って記述することになります。",
  'footing.cad.refusal.incompatibleWithV1': "基礎 {footing}: 組立には、RcCadHandoffV1 が宣言していない種別（{families}）の鉄筋が {bars} 本含まれています。V1 は固定されており、柱のダボ筋と差し筋の帯筋のみを扱います。それらの鉄筋をどちらかの種別として記述すると誤りになり、省略すると存在する鋼材を隠すことになります。それらを扱う RcCadHandoffV2 をエクスポートしてください。",
  'footing.cad.refusal.noStubExtent': "基礎 {footing}: 柱スタブは z = {base} m から z = {top} m にわたりますが、これは立体ではありません。",
  'footing.cad.refusal.stale': "基礎 {footing}: かごは断面力の改訂 {generated} に対して生成されましたが、モデルは現在 {current} です。エクスポートする前に詳細設計を再生成してください。",
  'footing.cad.refusal.invalid': "マニフェストは自身の検証に失敗しました: スキーマの問題 {schema} 件、意味上の問題 {semantic} 件。何もダウンロードされませんでした。",
  'footing.cad.ui.title': "CAD への引き渡し",
