  'otherCodes.code.ec2': "EN 1992-1-1",
  'otherCodes.coverage.aisc360': "二軸対称の I 形・H 形断面と鋼管について、引張、圧縮 (E3、細長い要素は E7 による低減)、横ねじれ座屈を考慮した曲げ (F2、Cb = 1、荷重は上フランジ)、せん断 (G2)、組合せ (H1) を検定します。曲げでノンコンパクトまたは細長い断面、および Cv1 < 1 のせん断は「未評価」と表示します。各部材には、それぞれに指定した長さと K を使います。",
  'otherCodes.coverage.ec3': "I 形・H 形断面 (圧延カタログから選んだ場合は圧延、それ以外は溶接) と冷間成形の鋼管について、曲げ座屈 (表 6.2 の曲線)、横ねじれ座屈 (6.3.2、C1 = 1、荷重は上フランジ)、曲げ、せん断、軸力を検定します。クラスは隅肉半径なしで判定し、クラス 4 の I 形と RHS は EN 1993-1-5 の有効断面を使い、クラス 4 の CHS は対象外です。6.3.3 の相関式は付属書 B の係数を使い、Cm = 1 とします。曲げを伴うせん断とウェブのせん断座屈は「未評価」と表示します。",
  'otherCodes.coverage.aisiS100': "リップ付き C 形の単一板断面について、有効幅 (付属書 1)、圧縮、引張、横ねじれ座屈を考慮した曲げ (F2.1)、降伏範囲のウェブせん断、組合せを検定します。ディストーショナル座屈は評価しないため、合格と表示される行はありません。圧縮での曲げねじれ座屈と弱軸まわりの曲げも評価しません。Z 形断面は対象外です。",
  'otherCodes.coverage.aci318': "各部材に指定した鉄筋を持つ矩形断面について、軸力を伴う曲げ (P–M 線図) とあばら筋によるせん断を検定します。梁は領域 (支点部とスパン中央部) ごと、柱は両面の鉄筋で検定します。鉄筋は 420 MPa、かぶりは 2.5 cm で、CIRSOC の設計と同じです。両方の軸まわりに曲げを受ける部材は対象外です。",
  'otherCodes.coverage.ec2': "指定した鉄筋を持つ矩形の梁について、γc = 1.5、γs = 1.15、αcc = 1 で曲げ (6.1) とせん断 (6.2) を検定します。曲げでは軸力を考慮しないため柱は対象外で、軸力が 0.1·fcd·Ac を超える梁は「未評価」と表示します。鉄筋は 420 MPa、かぶりは 2.5 cm で、CIRSOC の設計と同じです。",
