  'autoLoad.patternsHint': "市松配置 (パネルとスパンを交互に載荷し、階ごとに反転させたもの) は大きな正のモーメントを生じ、通りの両側のスパンと、その先で 1 つおきのスパンを載荷した配置は負のモーメントを生じます。各配置は 1 つのケースとなり、その荷重が主たる作用となる組合せで全荷重に置き換わります。低減した Lr にも同じことが当てはまります (表 4.1、注 n)。",
