  'wind.other.flexibleAssumedRigid': "構造物は柔として指定されていますが、§1.9.5 のガスト影響係数 Gf は実装されていません。剛な構造物の G = 0.85 を使用したため、不足する場合があります。Gf で確認してください。",
  'wind.other.hOverL': "h/L = {r}、図 2.4-4 から 2.4-7 の 0.25 から 1.0 の範囲外です。",
  'wind.other.freeRoof': "独立屋根 ({kind}、θ = {theta}°): qh = {qh} kN/m²、G = 0.85、CN は図 2.4-4 から 2.4-7 から求めます。",
  'wind.other.solidSign': "風 {dir} を受ける看板: B = {b} m、s = {s} m、h = {h} m、Cf = {cf}、F = {f} kN。",
  'wind.other.byHeight': "構造物 ({kind}) に作用する風 {dir}: {levels} 階層、合計 {f} kN。",
  'wind.cladding.title': "部分と外装材 (第 5 章)",
  'wind.cladding.area': "要素の有効風圧面積",
  'wind.cladding.basis': "p = qh[(GCp) − (GCpi)]、qh = {qh} kN/m²、GCpi の両方の符号を考慮し、最小値は 0.80 kN/m²。a = 壁で {a} m、屋根で {aRoof}。",
  'wind.cladding.aDrawn': "図 5.3-2A の描き方による",
  'wind.cladding.surface': "面",
  'wind.cladding.zone': "ゾーン",
  'wind.cladding.wall': "壁",
  'wind.cladding.roof': "屋根",
  'wind.cladding.note': "板材、母屋、外装材とその固定具の設計用です。モデルには適用しません。軒の出がない場合に限り、段付き、多スパン、ヴォールト、ドームの屋根は対象外です。",
  'wind.cladding.refused.slope': "屋根の勾配が、その種類の図の範囲外です (寄棟: 27° と 45° まで、片流れ: 30° まで、切妻とのこぎり屋根: 45° まで)。",
  'snow.note.notCoveredPanels': "軒に沿った氷ダム (§4.5) と、高い屋根としてモデル化されていない突出部に対する吹きだまり (第 8 章) は生成されません。",
  'snow.derivation.drift': "+{z} m から +{up} m への段差 (§7.1): hb = {hb} m、hc = {hc} m、風下側 hd {lee} m、風上側 {wind} m (図 9)。高さ {h} m、幅 {w} m の三角形で、pd = {pd} kN/m²、平衡積雪に加算します。",
  'snow.derivation.noDrift': "+{z} m から +{up} m への段差: hc/hb = {hc}/{hb} < 0.2、吹きだまりなし (§7.1)。",
  'snow.derivation.sliding': "+{z} m の屋根に滑り落ちる雪 (第 9 章): 勾配 {slope} %、W = {W} m、0.4 pf W = 4.5 m にわたり {perMetre} kN/m、{p} kN/m²、平衡積雪に加算します。",
  'snow.derivation.noSliding': "+{z} m の上の屋根は勾配 {slope} % で、雪が滑り落ちるには足りません (第 9 章)。",
  'snow.case.flatRoof': "平屋根の併用積雪 (pf)",
  'snow.refused.legacyCombination': "この保存済みの地震荷重組合せは、積雪の基準があいまいです。使用する前に組合せを再生成してください。積雪荷重だけを再生成しても不十分です。",
  'snow.refused.flatRoofCase': "この組合せには、平屋根の積雪ケースが別に必要です。組合せを生成する前に積雪荷重を再生成してください。",
  'combos.refused.unresolvedGroup': "記号 {symbol} とグループ「{group}」に一致する荷重ケースがありません。保存した組合せの規則と荷重ケースを確認してください。",
  'combos.refused.alternativeSet': "規則「{rule}」では、同じ方向性荷重記号のケースを組み合わせずに、択一の集合「{set}」のすべてのケースを表現することができません。規則と択一の集合を確認してください。",
  'combos.refused.directionalCase': "規則「{rule}」では、方向性荷重ケース「{case}」がどの組合せにも入りません。規則と択一の集合を確認してください。",
  'combos.refused.factorTotal': "規則「{rule}」の荷重係数の合計を、有限の数として表せません。規則の係数を確認してください。",
  'snow.refused.physicalCase': "この組合せには、実在の積雪ケースが別に必要です。組合せを生成する前に積雪荷重を再生成してください。",
  'snow.case.balanced': "平衡積雪 (ps = {ps} kN/m²)",
  'snow.derivation.multipleUnbalanced': "偏在荷重 (§6.3、図 6): 棟では 0.5 pf から谷では {valley} kN/m² まで。谷の上の積雪は棟の上の積雪を下回るようにします。",
  'snow.derivation.multiple': "複数の棟をもつ屋根 (§6.3): 棟 {ridges} 本と谷 {valleys} か所、最急勾配 {slope}°。Cs = 1 で、平衡積雪は pf = {pf} kN/m²。",
  'snow.curved.flat': "なし: その側には勾配がありません",
  'snow.curved.steep': "なし: 軒から頂部までの線が 60° を超えています",
  'snow.curved.shallow': "なし: 軒から頂部までの線が 10° 未満です",
  'snow.curved.case': "図 3 のケース {case} (軒 {eave}°、軒から頂部までの線 {line}°)",
  'snow.curved.caseAbutting': "図 3 のケース {case}、地面または他の屋根に接する場合: 30° の点の荷重を軒まで維持します (軒 {eave}°、軒から頂部までの線 {line}°)",
  'snow.derivation.dome': "半径 {r} m のドーム (§4.3 と §6.4): Cs は各点の勾配による。風下側の 90° の扇形で偏在、{unbalanced}。",
  'snow.derivation.curved': "曲面屋根 (§4.3): Cs は各点の勾配による。70° を超えると積雪なし。偏在荷重 (§6.2、図 3): 風が + 向きの場合は {plus}、− 向きの場合は {minus}。",
  'snow.derivation.edgeInterval': "縁の区間: 最初の縁の頂点から {from}–{to} m、値は {at} m の位置。",
  'snow.derivation.noAdjacent': "{side} に別の構造物があり、+{z} m の屋根から {s} m: 6 m 以上、または hc/hb < 0.2 の場合は吹きだまりなし (§7.2)。",
  'snow.derivation.adjacent': "{side} に別の構造物があり、その屋根は +{top} m で {s} m 離れています (§7.2)。+{z} m の屋根の隣: hb = {hb} m、hc = {hc} m。高さ {h} m ((6 − s)/6 で低減)、幅 {w} m の三角形で、pd = {pd} kN/m²、平衡積雪に加算します。",
  'snow.derivation.noParapet': "+{z} m の屋根の縁にある高さ {hp} m のパラペット: hc/hb = {hc}/{hb} < 0.2、吹きだまりなし (第 8 章)。",
  'snow.derivation.parapet': "+{z} m の屋根の縁にある高さ {hp} m のパラペット (第 8 章): lu = {lu} m、hb = {hb} m、hc = {hc} m、0.75 hd = {hd} m。高さ {h} m、幅 {w} m の三角形で、pd = {pd} kN/m²、平衡積雪に加算します。",
  'snow.derivation.partialExempt': "{axis} に沿った、棟に直角のスパンには部分荷重を適用しません。勾配 {slope}° が 21/W + 0.5 = {limit}° を超えています (§5.1)。",
  'snow.derivation.noPartial': "部分荷重 (§5.1): どちらの方向にも、屋根に 3 スパン連続する箇所がありません。追加する配置はありません。",
  'snow.derivation.intensityBound': "2 次の負担荷重強度には、力と平面の両方のモーメントを保存する区分線形荷重を使います。各実在の帯全体で、点ごとの誤差は標本化した荷重強度の最大値の {relativePercent}% 以下で、絶対値の最大の上限は {absolute} kN/m です。",
  'snow.derivation.partial': "部分荷重 (§5.1): 平衡積雪の配置 {n} 通り。一部のスパンには全部、残りには半分を載せ、積雪が主たる作用となる組合せで平衡積雪の代わりに入ります。",
