  'certificate.tooltip': "Lean で証明された厳密な事後上界です。組み立てた線形システムの厳密解は、計算した変位と最大でもこの量しか違いません（すべての自由度にわたるユークリッドノルムで、メートルとラジアンをまとめて扱います）。部材力の横の ± も、同じ方法でその誤差を抑えます。",
  'discretization.tooltip': "2 種類の異なる誤差です。代数誤差（保証済み）は、計算した変位が、組み立てた有限要素システムの厳密解からどれだけ離れているかを示す、厳密な上界です。離散化誤差（推定）は、そのシステムが、メッシュが表す構造からどれだけ離れているかを示します。メッシュに依存し、エネルギーノルム（膜と曲げ）での Zienkiewicz–Zhu 応力回復によって推定され、保証されてはいません。",
