  'certificate.comboTooltip': "Lean で証明された厳密な上界です。各荷重ケースは、組み立てたシステムの厳密解に対して保証されます。組合せの上界は、各ケースの上界に |係数| を掛けたものと、組合せ自体の丸め誤差を加えたものです。包絡線は、厳密な包絡線から最大の組合せの上界の範囲内にあります。部材力の横の ± も、同じ方法でその誤差を抑えます。",
