  'certificate.harmonicTooltip': "計算されたすべての振動数で、応答自由度における Rayleigh 減衰モデルの厳密な定常応答に対する厳密な包含区間です。厳密なピーク振幅は区間内にあり、報告されるすべての値は、モードの打切りを含めて、その厳密値の上界内にあります。位相には上界がありません。Lean では形式化されていません。",
